/**
 * Charge an amount to the customer's card.
 * @param amount the amount in cents
 * @returns after the payment provider accepts the charge
 */
export async function charge(amount: number): Promise<void> {
    const response = await fetch('https://payments.example.com/charges', {
        method: 'POST',
        body: JSON.stringify({ amount }),
    });
    if (!response.ok) throw new Error(`The charge failed with status ${String(response.status)}.`);
}

